    @if (isLoading)
    {
        <div class="d-flex justify-content-center py-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <ChangePasswordPanel SettingsService="SettingsService" LastPasswordChange="settings?.LastPasswordChange" />

        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <span class="badge @(twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@twoFactorEnabled" @onchange="ToggleTwoFactor" />
                    <label class="form-check-label" for="twoFactor"></label>
                </div>
            </div>
        </div>

        <div class="card">
            <div class="card-header">
                <h6 class="mb-0">Active Sessions</h6>
            </div>
            <div class="card-body p-0">
                @if (sessions.Count == 0)
                {
                    <p class="text-muted p-3 mb-0">No active sessions.</p>
                }
                else
                {
                    <div class="table-responsive">
                        <table class="table table-hover mb-0">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("g")</td>
                                        <td>
                                            @if (session != sessions[0])
                                            {
                                                <button class="btn btn-sm btn-outline-danger"
                                                        @onclick="() => sessionToRevoke = session">
                                                    Revoke
                                                </button>
                                            }
                                            else
                                            {
                                                <span class="badge bg-info">Current</span>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>
                }
            </div>
        </div>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show mt-3" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <RevokeSessionDialog Session="sessionToRevoke"
                             OnConfirm="RevokeSessionAsync"
                             OnCancel="() => sessionToRevoke = null" />
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? settings;
    private bool twoFactorEnabled;
    private List<ActiveSession> sessions = [];
    private ActiveSession? sessionToRevoke;
    private bool isLoading = true;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        settings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = settings.TwoFactorEnabled;
        sessions = [.. settings.Sessions];
        isLoading = false;
    }

    private void ToggleTwoFactor(ChangeEventArgs e)
    {
        twoFactorEnabled = (bool)e.Value!;
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        statusMessage = null;
        try
        {
            await SettingsService.RevokeSessionAsync(sessionId);
            sessions.RemoveAll(s => s.Id == sessionId);
            statusMessage = "Session revoked successfully.";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to revoke session: {ex.Message}";
            isError = true;
        }
        finally
        {
            sessionToRevoke = null;
        }
    }
}

