@code {
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnConfirm { get; set; }
    [Parameter, EditorRequired] public EventCallback OnCancel { get; set; }

    private bool isRevoking;

    private async Task ConfirmRevoke()
    {
        if (Session is null) return;
        isRevoking = true;
        await OnConfirm.InvokeAsync(Session.Id);
        isRevoking = false;
