    private async Task Cancel() => await OnCancel.InvokeAsync();
}
"}

{"path": "/tmp/sv-ff43c5771792486e9c6f7ed6bd1257ee/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_ff43c5771792486e9c6f7ed6bd1257ee.Components.Pages.Settings
@using sv_ff43c5771792486e9c6f7ed6bd1257ee.Services

<div class="settings-section">
    <h3>Security</h3>
    <p class="text-muted">Manage your account security</p>

    @if (isLoading)
    {
        <div class="d-flex justify-content-center py-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <ChangePasswordPanel SettingsService="SettingsService" LastPasswordChange="settings?.LastPasswordChange" />

        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <span class="badge @(twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@twoFactorEnabled" @onchange="ToggleTwoFactor" />
                    <label class="form-check-label" for="twoFactor"></label>
                </div>
            </div>
        </div>

        <div class="card">
            <div class="card-header">
                <h6 class="mb-0">Active Sessions</h6>
            </div>
            <div class="card-body p-0">
                @if (sessions.Count == 0)
                {
                    <p class="text-muted p-3 mb-0">No active sessions.</p>
                }
                else
                {
                    <div class="table-responsive">
                        <table class="table table-hover mb-0">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("g")</td>
                                        <td>
                                            @if (session != sessions[0])
                                            {
                                                <button class="btn btn-sm btn-outline-danger"
                                                        @onclick="() => sessionToRevoke = session">
                                                    Revoke
                                                </button>
                                            }
                                            else
                                            {
                                                <span class="badge bg-info">Current</span>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>
                }
            </div>
        </div>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show mt-3" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <RevokeSessionDialog Session="sessionToRevoke"
                             OnConfirm="RevokeSessionAsync"
                             OnCancel="() => sessionToRevoke = null" />
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? settings;
    private bool twoFactorEnabled;
    private List<ActiveSession> sessions = [];
    private ActiveSession? sessionToRevoke;
    private bool isLoading = true;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        settings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = settings.TwoFactorEnabled;
        sessions = [.. settings.Sessions];
        isLoading = false;
    }

    private void ToggleTwoFactor(ChangeEventArgs e)
    {
        twoFactorEnabled = (bool)e.Value!;
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        statusMessage = null;
        try
        {
            await SettingsService.RevokeSessionAsync(sessionId);
            sessions.RemoveAll(s => s.Id == sessionId);
            statusMessage = "Session revoked successfully.";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to revoke session: {ex.Message}";
            isError = true;
        }
        finally
        {
            sessionToRevoke = null;
        }
    }
}
"}

{"path": "/tmp/sv-ff43c5771792486e9c6f7ed6bd1257ee/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_ff43c5771792486e9c6f7ed6bd1257ee.Components.Pages.Settings
@using sv_ff43c5771792486e9c6f7ed6bd1257ee.Services

<div class="settings-section">
    <h3>Appearance</h3>
    <p class="text-muted">Customize how the app looks and feels</p>

    @if (isLoading)
    {
        <div class="d-flex justify-content-center py-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <div class="row g-4">
            <div class="col-md-6">
                <div class="mb-4">
                    <h5>Theme</h5>
                    @foreach (var t in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{t}")"
                                   value="@t" checked="@(theme == t)" @onchange="() => theme = t" />
                            <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h5>Font Size</h5>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                   value="@size" checked="@(fontSize == size)" @onchange="() => fontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <label class="form-label" for="language"><h5 class="d-inline">Language</h5></label>
                    <select id="language" class="form-select" @bind="language">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                        <option value="zh">中文</option>
                    </select>
                </div>

                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                        <label class="form-check-label" for="compactMode">
                            <h5 class="d-inline">Compact Mode</h5>
                        </label>
                    </div>
                </div>
            </div>

            <div class="col-md-6">
                <h5>Preview</h5>
                <div class="appearance-preview @PreviewThemeClass" style="@PreviewStyle">
                    <div class="preview-header">
                        <strong>Sample Header</strong>
                    </div>
                    <div class="preview-body" style="@(compactMode ? "padding: 0.5rem;" : "padding: 1rem;")">
                        <p class="mb-1">This is a preview of your selected appearance settings.</p>
                        <p class="mb-1 text-muted">Theme: @theme · Font: @fontSize · Compact: @(compactMode ? "On" : "Off")</p>
                        <button class="btn btn-sm btn-primary mt-1">Sample Button</button>
                    </div>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show mt-3" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@isSaving">
            @if (isSaving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private string theme = "System";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;

    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;
    private bool isError;

    private string PreviewThemeClass => theme switch
    {
        "Dark" => "preview-dark",
        "Light" => "preview-light",
        _ => "preview-system"
    };

    private string PreviewStyle => fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    protected override async Task OnInitializedAsync()
    {
        var appearance = await SettingsService.GetAppearanceAsync();
        theme = appearance.Theme;
        fontSize = appearance.FontSize;
        language = appearance.Language;
        compactMode = appearance.CompactMode;
        isLoading = false;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var settings = new AppearanceSettings(theme, fontSize, language, compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            statusMessage = "Appearance settings saved!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }
}
"}

