@namespace sv_ff43c5771792486e9c6f7ed6bd1257ee.Components.Pages.Settings
@using sv_ff43c5771792486e9c6f7ed6bd1257ee.Services

<div class="card mb-4">
    <div class="card-header d-flex justify-content-between align-items-center"
         role="button" @onclick="() => isExpanded = !isExpanded">
        <span>🔑 Change Password</span>
        <span>@(isExpanded ? "▲" : "▼")</span>
    </div>
    @if (isExpanded)
    {
        <div class="card-body">
            @if (LastPasswordChange.HasValue)
            {
                <p class="text-muted small">Last changed: @LastPasswordChange.Value.ToString("MMMM d, yyyy")</p>
            }

            <div class="mb-3">
                <label class="form-label" for="currentPwd">Current Password</label>
                <input id="currentPwd" type="password" class="form-control" @bind="currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="newPwd">New Password</label>
                <input id="newPwd" type="password" class="form-control" @bind="newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="confirmPwd">Confirm New Password</label>
                <input id="confirmPwd" type="password" class="form-control" @bind="confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(statusMessage))
            {
                <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                    @statusMessage
                    <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
                </div>
            }

            <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@isUpdating">
                @if (isUpdating)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Update Password
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;
    [Parameter] public DateTime? LastPasswordChange { get; set; }

    private bool isExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool isUpdating;
    private string? statusMessage;
    private bool isError;

    private async Task UpdatePasswordAsync()
    {
        statusMessage = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            statusMessage = "Please fill in all password fields.";
            isError = true;
            return;
        }

        if (newPassword != confirmPassword)
        {
            statusMessage = "New password and confirmation do not match.";
            isError = true;
            return;
        }

        isUpdating = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            statusMessage = "Password updated successfully!";
            isError = false;
            currentPassword = "";
            newPassword = "";
