@namespace sv_ff43c5771792486e9c6f7ed6bd1257ee.Components.Pages.Settings
@using sv_ff43c5771792486e9c6f7ed6bd1257ee.Services

<div class="settings-section">
    <h3>Appearance</h3>
    <p class="text-muted">Customize how the app looks and feels</p>

    @if (isLoading)
    {
        <div class="d-flex justify-content-center py-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <div class="row g-4">
            <div class="col-md-6">
                <div class="mb-4">
                    <h5>Theme</h5>
                    @foreach (var t in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{t}")"
                                   value="@t" checked="@(theme == t)" @onchange="() => theme = t" />
                            <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h5>Font Size</h5>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                   value="@size" checked="@(fontSize == size)" @onchange="() => fontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <label class="form-label" for="language"><h5 class="d-inline">Language</h5></label>
                    <select id="language" class="form-select" @bind="language">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                        <option value="zh">中文</option>
                    </select>
                </div>

                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                        <label class="form-check-label" for="compactMode">
                            <h5 class="d-inline">Compact Mode</h5>
                        </label>
                    </div>
                </div>
            </div>

            <div class="col-md-6">
                <h5>Preview</h5>
                <div class="appearance-preview @PreviewThemeClass" style="@PreviewStyle">
                    <div class="preview-header">
                        <strong>Sample Header</strong>
                    </div>
                    <div class="preview-body" style="@(compactMode ? "padding: 0.5rem;" : "padding: 1rem;")">
                        <p class="mb-1">This is a preview of your selected appearance settings.</p>
                        <p class="mb-1 text-muted">Theme: @theme · Font: @fontSize · Compact: @(compactMode ? "On" : "Off")</p>
                        <button class="btn btn-sm btn-primary mt-1">Sample Button</button>
                    </div>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show mt-3" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@isSaving">
            @if (isSaving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private string theme = "System";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;

    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;
    private bool isError;

    private string PreviewThemeClass => theme switch
    {
        "Dark" => "preview-dark",
        "Light" => "preview-light",
        _ => "preview-system"
    };

    private string PreviewStyle => fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    protected override async Task OnInitializedAsync()
    {
        var appearance = await SettingsService.GetAppearanceAsync();
        theme = appearance.Theme;
        fontSize = appearance.FontSize;
        language = appearance.Language;
        compactMode = appearance.CompactMode;
        isLoading = false;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var settings = new AppearanceSettings(theme, fontSize, language, compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            statusMessage = "Appearance settings saved!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }
}

