@page "/settings"
@using sv_ff43c5771792486e9c6f7ed6bd1257ee.Components.Pages.Settings
@using sv_ff43c5771792486e9c6f7ed6bd1257ee.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionSelected="section => activeSection = section" />

    <div class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection SettingsService="SettingsService" />
                break;
            case "Notifications":
                <NotificationsSection SettingsService="SettingsService" />
                break;
            case "Security":
                <SecuritySection SettingsService="SettingsService" />
                break;
            case "Appearance":
                <AppearanceSection SettingsService="SettingsService" />
                break;
        }
    </div>
</div>

@code {
    private string activeSection = "Profile";
}

.settings-dashboard {
    display: flex;
    min-height: 80vh;
    gap: 0;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
}

::deep .settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

::deep .sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    border-bottom: 1px solid #dee2e6;
}

::deep .settings-sidebar .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.15s, color 0.15s;
}

::deep .settings-sidebar .nav-link:hover {
    background: #e9ecef;
    color: #212529;
}

::deep .settings-sidebar .nav-link.active {
    background: #0d6efd;
    color: #fff;
    font-weight: 500;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

::deep .settings-section h3 {
    margin-bottom: 0.25rem;
}

::deep .avatar-preview {
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    border: 1px solid #dee2e6;
}

::deep .avatar-placeholder {
    width: 120px;
    height: 120px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    background: #e9ecef;
    margin: 0 auto;
}

/* Appearance preview */
::deep .appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    min-height: 160px;
}

::deep .preview-light {
    background: #ffffff;
    color: #212529;
}

::deep .preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
}

::deep .preview-system {
    background: #f0f0f5;
    color: #333;
}

::deep .preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid rgba(128, 128, 128, 0.2);
}

::deep .preview-dark .preview-header {
    background: #181825;
}

::deep .preview-light .preview-header {
    background: #f8f9fa;
}

